    static float Hf4b(string h) => BitConverter.Int32BitsToSingle(unchecked((int)Convert.ToUInt32(h, 16)));
    static float[] Fv4b(string bars) => bars.Split('|').Select(Hf4b).ToArray();
    static Vector2[] Pts4b(string s) => s.Split(' ', StringSplitOptions.RemoveEmptyEntries).Select(p => { var xy = p.Split(':'); return new Vector2(Hf4b(xy[0]), Hf4b(xy[1])); }).ToArray();
    static Vector2[][] Paths4b(string s) => s.Length == 0 ? Array.Empty<Vector2[]>() : s.Split(" / ").Select(Pts4b).ToArray();
    static Vector2[][] Pieces4b(string s) => s.Trim().Length == 0 ? Array.Empty<Vector2[]>() : s.Split(" | ").Select(Pts4b).ToArray();
    static void Pose4b(Transform t, string p, string q, string s, bool local)
    {
        var pv = Fv4b(p); var qv = Fv4b(q); var sv = Fv4b(s);
        if (local) t.localPosition = new Vector3(pv[0], pv[1], pv[2]); else t.position = new Vector3(pv[0], pv[1], pv[2]);
        t.localRotation = new Quaternion(qv[0], qv[1], qv[2], qv[3]);
        t.localScale = new Vector3(sv[0], sv[1], sv[2]);
    }
    static string Same4bText(Vector2[][] ours, Vector2[][] unity)
    {
        if (ours.Length != unity.Length) return $"{ours.Length} / {unity.Length} (ours / Unity's)";
        int bad = 0, pts = 0; string first = "";
        for (int k = 0; k < unity.Length; k++)
        {
            if (!Same4(ours[k], unity[k])) { bad++; if (first.Length == 0) first = $"[{k}] ours {P4(ours[k])} Unity {P4(unity[k])}"; }
            pts += unity[k].Length;
        }
        return bad == 0 ? $"{unity.Length} ({pts} points) bit for bit" : $"{bad} of {unity.Length} differ: {first}";
    }

    /// <summary>Without the owner-local offsetter: the paths bit for bit (each with its start), in any order.</summary>
    static string Same4bAnyOrder(Vector2[][] ours, Vector2[][] unity)
    {
        if (ours.Length != unity.Length) return $"{ours.Length} / {unity.Length} (ours / Unity's)";
        var used = new bool[ours.Length]; int pts = 0;
        for (int k = 0; k < unity.Length; k++)
        {
            int m = -1;
            for (int j = 0; j < ours.Length && m < 0; j++) if (!used[j] && Same4(ours[j], unity[k])) m = j;
            if (m < 0) return $"Unity's path [{k}] has no equal: {P4(unity[k])}";
            used[m] = true; pts += unity[k].Length;
        }
        return $"{unity.Length} ({pts} points) bit for bit";
    }

    static void Unit4b()
    {
        Up();
        Runtime.Time.CaptureDeltaTime = 1f / 50f;
        bool dec = DerivedPhysics.Decomposer != null;
        bool ofs = DerivedPhysics.Offsetter != null;
        Log.Info($"[physcheck]      unit4b: the owner-local decomposer: {DerivedPhysics.Status}" + (dec ? "" : " -- the H-DECOMP checks are skipped") +
                 (ofs ? "" : "; no offsetter -- the composites' path order is not checked (the game's own OffsetPolygons orders ties its way)"));
        var made = new List<GameObject>();
        // ---- composites (H-STARTVTX; Polygons ones also H-DECOMP) ----
        var comps = new List<(string tag, char geom, Component cc, string paths, string shapes)>();
        foreach (var c in Comp4b)
        {
            var g = new GameObject("U4b " + c.tag); made.Add(g);
            Pose4b(g.transform, c.p, c.q, c.s, false);
            g.AddComponent<Rigidbody2D>().bodyType = RigidbodyType2D.Static;
            var cc = (CompositeCollider2D)Comp4(g, true);
            cc.geometryType = c.geom == 'P' ? CompositeCollider2D.GeometryType.Polygons : CompositeCollider2D.GeometryType.Outlines;
            if (c.tag.EndsWith("_min") || c.tag.StartsWith("U_min")) { cc.offsetDistance = 0f; cc.vertexDistance = 0f; }   // (Paths4b2: the union alone)
            int i = 0;
            foreach (var s in c.ins)
            {
                var k = new GameObject($"U4b {c.tag} in{i++}"); k.transform.SetParent(g.transform, false); Pose4b(k.transform, s.p, s.q, s.s, true);
                var off = Pts4b(s.off)[0];
                if (s.kind == 'B') { var b = k.AddComponent<BoxCollider2D>(); var sz = Fv4b(s.data.Replace(':', '|')); b.size = new Vector2(sz[0], sz[1]); b.offset = off; b.usedByComposite = true; }
                else { var pc = k.AddComponent<PolygonCollider2D>(); var ps = Paths4b(s.data); pc.pathCount = ps.Length; for (int j = 0; j < ps.Length; j++) pc.SetPath(j, ps[j]); pc.offset = off; pc.usedByComposite = true; }
            }
            cc.GenerateGeometry();
            comps.Add((c.tag, c.geom, cc, c.paths, c.shapes));
        }
        // ---- polygon colliders (H-DECOMP) ----
        var polys = new List<(string tag, Component pc, string shapes)>();
        foreach (var c in Poly4b)
        {
            var g = new GameObject("U4b " + c.tag); made.Add(g);
            Pose4b(g.transform, c.p, c.q, c.s, false);
            if (c.body is 'S' or 'K') { var rb = g.AddComponent<Rigidbody2D>(); rb.bodyType = c.body == 'S' ? RigidbodyType2D.Static : RigidbodyType2D.Kinematic; }
            var pc = g.AddComponent<PolygonCollider2D>(); var ps = Paths4b(c.paths); pc.pathCount = ps.Length; for (int j = 0; j < ps.Length; j++) pc.SetPath(j, ps[j]);
            pc.offset = Pts4b(c.off)[0];
            polys.Add((c.tag, pc, c.shapes));
        }
        PhysWorld.Flush();
        int cpass = 0, ppass = 0, cdec = 0, pdec = 0;
        foreach (var (tag, geom, cc, paths, shapes) in comps)
        {
            var ours = CompPaths4(cc); var unity = Pieces4b(paths);
            string r = ofs ? Same4bText(ours, unity) : Same4bAnyOrder(ours, unity); bool ok = r.EndsWith("bit for bit");
            Check($"U4b {tag} ({(geom == 'P' ? "Polygons" : "Outlines")}): GetPath = Unity's paths, every vertex, start{(ofs ? " and order" : " (any order)")}", ok, r);
            if (ok) cpass++;
            if (geom == 'P' && dec)
            {
                var sh = PhysWorld.ShapePolygons(Col(cc)); string rs = Same4bText(sh, Pieces4b(shapes)); bool oks = rs.EndsWith("bit for bit");
                Check($"U4b {tag} Polygons: the convex pieces = Unity's shapes (libtess2's pieces and order, Box2D's hull order)", oks, rs);
                if (oks) cdec++;
            }
        }
        if (dec)
            foreach (var (tag, pc, shapes) in polys)
            {
                var sh = PhysWorld.ShapePolygons(Col(pc)); string r = Same4bText(sh, Pieces4b(shapes)); bool ok = r.EndsWith("bit for bit");
                Check($"U4b {tag}: the polygon's shapes = Unity's (H-DECOMP: pieces, order, hull order, weld, collinear removal, snap)", ok, r);
                if (ok) ppass++;
            }
        Log.Info($"[physcheck]      unit4b: composites {cpass} / {comps.Count} paths bit for bit, {cdec} Polygons shape sets; polygon colliders {(dec ? $"{ppass} / {polys.Count}" : "skipped")}");
        foreach (var g in made) UObject.DestroyImmediate(g);
        Frames(2);
    }
}
#endif
